<script setup lang="ts">
import { tr } from '../../i18n/index.ts'

import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {Wrench,Plus,FolderOpen,Check,Sparkles} from 'lucide-vue-next'
import type {GameItem,LinkedFile} from '@/types'
import type {GameLinkState} from '@/types/game-project'
import {errorMessage,LINK_TYPE_LABEL,plain} from '@/utils'
import {useToast} from '@/composables/useToast'
import {useArchiveAssistant} from '@/composables/useArchiveAssistant'
import LibraryToolbarMenu from '@/components/library/LibraryToolbarMenu.vue'
import {TOOL_PURPOSE} from '@/utils/game-project'
import GameMarkdown from './GameMarkdown.vue'
const props=defineProps<{game:GameItem}>(),emit=defineEmits<{updated:[game:GameItem]}>()
const {error,toast}=useToast(),links=computed(()=>props.game.linked_files.filter(f=>f.type==='trainer'))
const query=ref(''),visible=computed(()=>links.value.filter(f=>(f.label+' '+f.path+' '+(f.usage||f.note||'')+' '+(f.features||[]).map(x=>x.label).join(' ')).toLowerCase().includes(query.value.toLowerCase())))
const purpose=ref<NonNullable<LinkedFile['purpose']>>('mixed')
const states=ref<GameLinkState[]>([]),busy=ref(false),editing=ref(''),usage=ref(''),version=ref(''),fit=ref(''),source=ref(''),features=ref(''),name=ref(''),expected=ref(''),reading=ref(''),text=ref('')
let sequence=0
const exists=(f:LinkedFile)=>states.value.find(s=>s.path===f.path)?.exists
const runnable=(f:LinkedFile)=>f.role!=='usage'&&/\.(exe|cmd|bat|lnk)$/i.test(f.path)
watch(()=>props.game.id+JSON.stringify(props.game.linked_files),async()=>{const n=++sequence;try{const s=await window.baoyi.game.linkStates(props.game.id);if(n===sequence)states.value=s}catch(e){if(n===sequence)error(errorMessage(e))}},{immediate:true})
onBeforeUnmount(()=>sequence++)
async function patch(f:LinkedFile,value:Partial<LinkedFile>|null,stamp=JSON.stringify(f)){busy.value=true;try{const result=await window.baoyi.game.patchLink(props.game.id,f.path,plain(value),stamp);if(result)emit('updated',result);return true}catch(e){error(errorMessage(e));return false}finally{busy.value=false}}
async function add(){busy.value=true;try{const result=await window.baoyi.game.pickLinks(props.game.id,'file','trainer');if(result)emit('updated',result)}catch(e){error(errorMessage(e))}finally{busy.value=false}}
async function open(f:LinkedFile,reveal=false){try{const r=await(reveal?window.baoyi.game.revealLink:window.baoyi.game.openLink)(props.game.id,f.path);if(!r.ok)error(r.message)}catch(e){error(errorMessage(e))}}
function edit(f:LinkedFile){purpose.value=f.purpose||'mixed';editing.value=f.path;expected.value=JSON.stringify(f);name.value=f.label;usage.value=f.usage||f.note||'';version.value=f.version||'';fit.value=f.fit_version||'';source.value=f.source||'';features.value=(f.features||[]).map(x=>(x.key?x.key+' | ':'')+x.label).join('\n')}
async function save(f:LinkedFile){const list=features.value.split('\n').filter(s=>s.trim()).map(line=>{const i=line.indexOf('|');return {key:i<0?'':line.slice(0,i).trim(),label:(i<0?line:line.slice(i+1)).trim()}});if(await patch(f,{purpose:purpose.value,label:name.value,usage:usage.value,version:version.value,fit_version:fit.value,source:source.value,features:list},expected.value))editing.value=''}
async function read(f:LinkedFile){try{const r=await window.baoyi.game.previewLink(props.game.id,f.path);if(r.kind==='md'||r.kind==='txt'){reading.value=f.path;text.value=r.text}else toast(tr("此格式请用系统程序打开"))}catch(e){error(errorMessage(e))}}
async function identify(f:LinkedFile){try{const docs=links.value.filter(x=>x.role==='usage'||/\.(txt|md)$/i.test(x.path));const snippets=[];for(const doc of docs.slice(0,4)){try{const p=await window.baoyi.game.previewLink(props.game.id,doc.path);snippets.push(doc.label+'\n'+p.text.slice(0,12000))}catch (cause) { useToast().error(errorMessage(cause)) }}const a=useArchiveAssistant();await a.show((a.draft.value?a.draft.value+'\n\n':'')+tr("请根据以下本地说明，整理「{p0}」的功能、快捷键、用法和适用版本。资料缺失的项目标为未知，不运行文件。输出每行「快捷键 | 功能」供我检查后粘贴到功能说明。\n\n", {p0: (f.label)})+snippets.join('\n\n'),[props.game.id]);toast(tr("识别请求已放入归档助理，确认后发送"))}catch(e){error(errorMessage(e))}}
</script>
<template>
 <section class="tools-panel"><header><span>{{ $t("{p0} 项修改器与工具", {p0: (links.length)}) }}</span><input v-model="query" class="tool-search" :aria-label="$t('搜索修改器与工具')" :placeholder="$t('搜索名称、功能或说明')"/><button class="btn btn--ghost" :disabled="busy||game.linked_files.length>=20" @click="add"><Plus :size="14"/>{{ $t("关联工具") }}</button></header>
 <p v-if="!links.length" class="tools-empty">{{ $t("还没有修改器。关联本地工具或使用说明，功能与用法会一起保存在这里。") }}</p>
 <p v-if="links.length&&!visible.length" class="tools-empty">{{ $t("没有匹配的工具，试试名称或功能关键词。") }}</p>
 <article v-for="file in visible" :key="file.path" class="tool-card"><div class="tool-head"><div class="tool-icon"><Wrench :size="20"/></div><div class="tool-title"><h3>{{file.label}} <small>{{file.role==='usage'?$t('使用说明'):file.purpose?TOOL_PURPOSE[file.purpose]:LINK_TYPE_LABEL[file.type]}}</small><small v-if="file.version">{{file.version}}</small></h3><p>{{file.fit_version?$t('适用版本：')+file.fit_version+$t(' · 当前游戏版本未核对'):$t('版本适配未知')}}</p></div><div class="tool-actions"><label v-if="runnable(file)" class="auto-start"><input type="checkbox" :checked="file.launch_with_game" :disabled="busy" @change="patch(file,{launch_with_game:($event.target as HTMLInputElement).checked})"/>{{ $t("随游戏启动") }}</label><button v-if="/\.(md|txt)$/i.test(file.path)" class="btn btn--ghost" :disabled="!exists(file)" @click="read(file)">{{ $t("阅读") }}</button><button class="btn btn--ghost" :disabled="!exists(file)" @click="open(file)">{{ $t("打开") }}</button><button class="btn btn--icon" :disabled="!exists(file)" :aria-label="$t('定位 ')+file.label" @click="open(file,true)"><FolderOpen :size="15"/></button><LibraryToolbarMenu icon="more" :label="$t('管理 ')+file.label"><button @click="edit(file)">{{ $t("编辑名称与功能说明") }}</button><label>{{ $t("类型") }}<select :value="file.type" :disabled="busy" @change="patch(file,{type:($event.target as HTMLSelectElement).value as LinkedFile['type']})"><option v-for="(label,key) in LINK_TYPE_LABEL" :key="key" :value="key">{{label}}</option></select></label><button :disabled="busy" @click="patch(file,null)">{{ $t("解除关联，保留文件") }}</button></LibraryToolbarMenu></div></div>
 <details v-if="file.usage||file.note" class="tool-usage"><summary>{{ $t("用法与注意事项") }}</summary><p>{{file.usage||file.note}}</p></details>
 <p v-if="exists(file)===false" class="tool-missing">{{ $t("文件缺失或所在磁盘未连接") }}</p>
 <form v-if="editing===file.path" class="tool-edit" @submit.prevent="save(file)"><label>{{ $t("名称") }}<input v-model="name" maxlength="100"/></label><label>{{ $t("工具用途") }}<select v-model="purpose" :aria-label="$t('工具用途')"><option v-for="(label,key) in TOOL_PURPOSE" :key="key" :value="key">{{label}}</option></select></label><label>{{ $t("工具版本") }}<input v-model="version" maxlength="500"/></label><label>{{ $t("适用游戏版本") }}<input v-model="fit" maxlength="500"/></label><label>{{ $t("来源") }}<input v-model="source" maxlength="500"/></label><label class="full">{{ $t("用法") }}<textarea v-model="usage" maxlength="4000"/></label><label class="full">{{ $t("功能说明（每行「快捷键 | 功能」，没有快捷键可只写功能）") }}<textarea v-model="features" rows="5"/></label><div class="full"><button class="btn btn--primary" :disabled="busy">{{ $t("保存功能说明") }}</button><button type="button" class="btn btn--subtle" @click="editing=''">{{ $t("取消") }}</button></div></form>
 <details v-else-if="file.features?.length" class="tool-features" :open="file.features.length<=3"><summary>{{ $t("功能与快捷键 · {p0}", {p0: (file.features.length)}) }}</summary><div class="features"><div v-for="(f,i) in file.features" :key="i"><kbd v-if="f.key">{{f.key}}</kbd><Check v-else :size="14"/>{{f.label}}</div></div></details><div v-else-if="file.role!=='usage'" class="feature-empty"><span>{{ $t("还不知道它能做什么") }}</span><button class="btn btn--subtle" @click="identify(file)"><Sparkles :size="13"/>{{ $t("AI 识别") }}</button><button class="btn btn--ghost btn--sm" @click="edit(file)">{{ $t("手动填写") }}</button></div>
 <div v-if="reading===file.path" class="tool-reading"><button class="btn btn--subtle" @click="reading=''">{{ $t("收起说明") }}</button><GameMarkdown :text="text"/></div>
 <footer><span class="mono" :title="file.path">{{file.path.split(/[\\/]/).pop()}}</span><span v-if="file.source">{{ $t("来源：{p0}", {p0: (file.source)}) }}</span><span>{{ $t("{p0} 项功能", {p0: (file.features?.length||0)}) }}</span></footer></article></section>
</template>
<style scoped>
.tools-panel>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;color:var(--text-faint);font-size:12px}.tool-card{border:1px solid var(--card-border);border-radius:12px;background:var(--bg-card);margin-bottom:16px;overflow:hidden}.tool-head{display:flex;gap:14px;align-items:flex-start;padding:20px}.tool-icon{padding:12px;border-radius:10px;background:var(--active-surface);color:var(--accent-ink)}.tool-title{flex:1;min-width:0}.tool-title h3{font-size:15px;display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:0 0 9px}.tool-title small{font-size:10px;font-weight:400;color:var(--text-sub);background:var(--bg-elevated);padding:3px 6px;border-radius:4px}.tool-title p{color:var(--text-faint);font-size:11px;line-height:1.8;white-space:pre-wrap}.tool-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.auto-start{display:flex;gap:5px;font-size:11px;color:var(--text-sub);align-items:center;margin-right:7px}.auto-start input{accent-color:var(--accent)}.features{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:2px 20px 20px;gap:10px}.features>div{display:flex;align-items:center;gap:10px;font-size:12px}.features svg{color:var(--success)}kbd{padding:3px 7px;border:1px solid var(--divider-strong);border-radius:4px;font:10px var(--font-mono);color:var(--text-sub)}.feature-empty{margin:0 20px 20px;padding:22px;border:1px dashed var(--divider-strong);border-radius:7px;display:flex;justify-content:center;align-items:center;gap:12px;font-size:12px;color:var(--text-faint)}footer{padding:10px 20px;display:flex;gap:15px;background:var(--bg-main);font-size:10px;color:var(--text-faint)}footer span:first-child{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tools-empty{padding:60px;color:var(--text-sub);text-align:center}.tool-missing{color:var(--warning);padding:0 20px 14px;font-size:12px}.tool-edit{padding:0 20px 20px;display:grid;grid-template-columns:1fr 1fr;gap:12px}.tool-edit label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--text-sub)}.tool-edit input,.tool-edit textarea,.tool-edit select{background:var(--bg-main);border:1px solid var(--divider-strong);border-radius:5px;padding:8px;width:100%}.full{grid-column:1/-1}.tool-reading{padding:20px;border-top:1px solid var(--divider)}@media(max-width:1180px){.tool-head{flex-wrap:wrap}.tool-actions{width:100%;padding-left:58px}.features{grid-template-columns:repeat(2,minmax(0,1fr))}}
.tool-usage,.tool-features{margin:0 20px 16px;font-size:12px;line-height:1.8}.tool-usage summary,.tool-features summary{cursor:pointer;color:var(--text-sub);padding:5px 0}.tool-usage p{white-space:pre-wrap;overflow-wrap:anywhere;margin-top:10px;max-width:85ch;color:var(--text-sub)}.tool-features .features{padding:12px 0 0}.features>div{align-items:flex-start;overflow-wrap:anywhere}.features svg,kbd{flex:none}.tools-panel>header{gap:10px;flex-wrap:wrap}.tool-search{min-width:130px}
</style>

<style scoped>.tool-search{margin-left:auto;margin-right:12px;width:220px;background:var(--bg-main);border:1px solid var(--divider-strong);padding:7px 9px;border-radius:6px;font-size:12px}</style>
